import type { Ref, TextareaHTMLAttributes } from 'react'
import { cn } from '@/lib/cn'

// Several lines of text, drawn as the Input is: a #363636 hairline on Black that turns White on focus, DM Sans at 14px
// (16px on phones, so iOS does not zoom), a #A3A3A3 placeholder, the brand corner, 10px 12px inside. It grows by hand
// downward only. `invalid` turns the hairline red. Put it in a Field for its label and description. Every other prop
// lands on the <textarea> (value and onChange as React's own).
export interface TextareaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  /** A red hairline (with the message under it). */
  invalid?: boolean
  /** Visible lines before it scrolls (4). */
  rows?: number
  ref?: Ref<HTMLTextAreaElement>
}

export function Textarea({ invalid, rows = 4, className, ...rest }: TextareaProps) {
  return (
    <textarea
      data-ds="textarea"
      {...rest}
      rows={rows}
      aria-invalid={invalid || undefined}
      className={cn('block w-full min-w-0 resize-y rounded-control border border-edge-strong bg-surface px-3 py-2.5 type-ui text-fg outline-none transition-[border-color] duration-150 ease-standard placeholder:text-fg-muted hover:not-disabled:border-action-secondary-edge-hover focus-visible:border-edge-focus aria-invalid:border-action-danger disabled:cursor-not-allowed disabled:text-fg-faint max-md:text-input pointer-coarse:text-input', className)}
    />
  )
}

export default Textarea

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
